const tests = $input.all().map(i => i.json);
if (!tests.length || !tests[0].test_id) return [];

const results = [];

for (const test of tests) {
  const variants = typeof test.variants === 'string' ? JSON.parse(test.variants) : test.variants;
  if (!variants || !variants.length) continue;

  results.push({
    json: {
      campaign_id: test.id,
      test_id: test.test_id,
      campaign_name: test.campaign_name,
      client_id: test.client_id,
      winning_metric: test.winning_metric || 'open_rate',
      variants: variants,
      variant_ids: variants.map(v => v.variant_id)
    }
  });
}

return results;

const stats = $input.all().map(i => i.json);
const testConfig = $node['Parse Tests'].json;

if (!stats.length) return [{ json: { ...testConfig, winner: null, reason: 'No stats available' } }];

// Calculate rates
const variantResults = stats.map(s => {
  const sent = parseInt(s.sent) || 1;
  return {
    variant_id: s.variant_id,
    variant_label: s.variant_label,
    sent: parseInt(s.sent) || 0,
    opened: parseInt(s.opened) || 0,
    clicked: parseInt(s.clicked) || 0,
    converted: parseInt(s.converted) || 0,
    open_rate: (parseInt(s.opened) || 0) / sent * 100,
    click_rate: (parseInt(s.clicked) || 0) / sent * 100,
    conversion_rate: (parseInt(s.converted) || 0) / sent * 100
  };
});

// Determine winner based on metric
const metric = testConfig.winning_metric;
const sorted = [...variantResults].sort((a, b) => b[metric] - a[metric]);
const winner = sorted[0];

// Statistical significance check (simplified)
const totalSent = variantResults.reduce((sum, v) => sum + v.sent, 0);
const isSignificant = totalSent >= 100 && (winner[metric] - sorted[1][metric]) > 2;

// Find winning subject line from original variants
const winningVariant = testConfig.variants.find(v => v.variant_id === winner.variant_id);

return [{
  json: {
    ...testConfig,
    results: variantResults,
    winner: {
      variant_id: winner.variant_id,
      variant_label: winner.variant_label,
      subject_line: winningVariant?.subject_line || 'Unknown',
      metrics: winner
    },
    is_significant: isSignificant,
    summary: `Variant ${winner.variant_label} wins with ${winner[metric].toFixed(1)}% ${metric.replace('_', ' ')}`
  }
}];

